        example: 'Представьте, что вы пришли в ресторан, а вам дают меню, где написано: "У нас есть блюдо "Пицца Маргарита", для его заказа нужно назвать размер (M или L) и количество. Мы вернём вам цену и время приготовления". WSDL — это такое же меню для программиста. В нём написано: "У сервиса есть метод getPrice, для него нужно передать параметры pizzaSize и quantity, ответ будет содержать price и deliveryTime". Программист читает WSDL и сразу понимает, как пользоваться сервисом.',
        academic: 'Это описание сервиса, написанное на XML. Оно говорит: вот какие методы есть у сервиса, какие параметры можно передавать, и в каком формате будет ответ.',
