        example: 'Вы делаете API для регистрации пользователей. В XSD вы прописываете: "Поле email обязательно и должно быть строкой. Поле age обязательно и должно быть числом. Поле name обязательно и должно быть строкой". Теперь, если кто-то пришлёт XML без поля email или с полем age="abcd" (строка вместо числа), система проверит этот XML по XSD и скажет: "Невалидный документ — поле age должно быть числом". XSD работает как строгий контролёр на входе.',
        academic: 'Это набор правил, по которым проверяется XML-документ: какие поля обязательны, какого они типа, в каком порядке.',
