        example: 'Вот как выглядит JSON-объект с данными пользователя: {"name": "John", "age": 30, "city": "Moscow", "isActive": true, "hobbies": ["reading", "swimming", "chess"]}. Это означает: у пользователя есть имя "John", возраст 30, город "Moscow", он активен (true), и у него есть три хобби. Массив из нескольких объектов выглядит так: [{"name": "John", "age": 30}, {"name": "Liza", "age": 55}, {"name": "Mike", "age": 25}]. JSON легко читать, легко писать, и любые программы на любых языках программирования умеют его обрабатывать.',
