        example: 'Разработчики описывают API в Swagger: все эндпоинты (GET /users, POST /users), все параметры (email, password), примеры запросов и ответов. Вы открываете Swagger UI в браузере и видите красивую страницу со всеми методами. Нажимаете на метод GET /users, вводите параметры, нажимаете "Try it out" — и Swagger отправляет реальный запрос к API и показывает ответ. Это удобно для тестирования, не нужно писать код.',
        academic: 'Это инструмент для описания REST API в формате JSON/YAML. Позволяет создавать интерактивную документацию, генерировать клиентский код и тестировать API непосредственно из браузера.',
