        simple: 'Процесс тестирования API включает: 1) Запросить документацию 2) Изучить методы 3) Создать коллекции в Postman 4) Запустить тестирование.',
        example: 'Вы тестируете API интернет-магазина. Вы проверяете: 1) Обязательные/необязательные поля — например, поле "email" обязательно, а "phone" — нет. 2) Отправку различных типов данных — числа, строки, массивы. 3) Статус-коды: 200 — успех, 400 — плохой запрос, 401 — не авторизован, 403 — нет прав, 404 — ресурс не найден, 500 — ошибка сервера. 4) Ответ от сервера: проверяете заголовки, тело ответа, все ключи и значения, типы данных. 5) Авторизацию и разрешения. 6) Время ответа: если запрос выполняется 10 секунд — это проблема.',
        academic: 'Как тестировать API: 1) Запросить документацию (WSDL для SOAP, Swagger для REST). 2) Изучить доступные методы. 3) Создать коллекции в Postman. 4) Запустить процесс тестирования. Что нужно проверять: обязательные/необязательные значения, типы данных, статус-коды, ответ сервера, авторизация, время ответа.',
