        tagColor: 'orange',
        simple: 'Основные правила, которые делают XML-документ корректным: 1) обязательное наличие корневого элемента, 2) закрывающие теги, 3) чувствительность к регистру, 4) правильное вложение, 5) кавычки в атрибутах, 6) специальные значения для спецсимволов.',
        example: 'Вот примеры ошибок и правильного написания в XML: 1) Обязательный корень: <tag1></tag1><tag2></tag2> — ошибка, правильно: <root><tag1></tag1><tag2></tag2></root>. 2) Закрывающие теги: <tag>Text<tag> — ошибка, правильно: <tag>Text</tag>. 3) Регистр: <Tag>example</tag> — ошибка (регистр не совпадает), правильно: <tag>example</tag>. 4) Вложение: <b><i>Text</b></i> — ошибка, правильно: <b><i>Text</i></b>. 5) Кавычки: <tag attribute=value></tag> — ошибка, правильно: <tag attribute="value"></tag>. 6) Спецсимволы: <tag> 5 < 10 </tag> — ошибка, правильно: <tag> 5 &lt; 10 </tag>.',
        academic: 'Основные правила синтаксиса XML: 1) Обязательный корневой элемент 2) Закрывающие теги 3) Чувствительность к регистру 4) Правильное вложение 5) Кавычки в значениях атрибутов 6) Использование спецсимволов (&lt; для <, &gt; для >, &amp; для &).',
        source: 'API.docx',
